function Send-DiscordMessage {
    param([string]$WebhookUrl = '', [string]$BotToken = '', [string]$ChannelId = '', [string]$Content = '', [string]$EmbedTitle = '', [string]$EmbedDescription = '', [int]$EmbedColor = 65280, [switch]$MentionEveryone, [string[]]$MentionRoles = @())
    if (-not $WebhookUrl -and -not $BotToken) { throw 'Either WebhookUrl or BotToken required' }
    $body = @{ content = $Content; allowed_mentions = @{} }
    if ($MentionEveryone) { $body.allowed_mentions.parse = @('everyone') }
    if ($MentionRoles.Count) { $body.allowed_mentions.roles = $MentionRoles }
    if ($EmbedTitle -or $EmbedDescription) {
        $body.embeds = @(@{ title = $EmbedTitle; description = $EmbedDescription; color = $EmbedColor })
    }
    $json = $body | ConvertTo-Json -Depth 5
    try {
        if ($WebhookUrl) {
            $response = Invoke-RestMethod -Uri $WebhookUrl -Method Post -Body $json -ContentType 'application/json' -ErrorAction Stop
            Write-SysLog "Discord message sent via webhook to channel $ChannelId" -Level 'INFO'
            return [PSCustomObject]@{ Success=$true; MessageId=$response.id; Error=$null }
        } else {
            $url = "https://discord.com/api/v10/channels/$ChannelId/messages"
            $headers = @{ Authorization = "Bot $BotToken" }
            $response = Invoke-RestMethod -Uri $url -Method Post -Body $json -Headers $headers -ContentType 'application/json' -ErrorAction Stop
            return [PSCustomObject]@{ Success=$true; MessageId=$response.id; Error=$null }
        }
    } catch {
        Write-SysLog "Discord send failed: $_" -Level 'ERROR'
        return [PSCustomObject]@{ Success=$false; MessageId=$null; Error=$_.Exception.Message }
    }
}

function Get-DiscordUserInfo {
    param([string]$BotToken, [string]$UserId, [string]$GuildId = '')
    $headers = @{ Authorization = "Bot $BotToken" }
    try {
        if ($GuildId) {
            $url = "https://discord.com/api/v10/guilds/$GuildId/members/$UserId"
            $member = Invoke-RestMethod -Uri $url -Headers $headers -ErrorAction Stop
            $user = $member.user
            return [PSCustomObject]@{
                Id = $user.id
                Username = $user.username
                Discriminator = $user.discriminator
                GlobalName = $user.global_name
                Avatar = $user.avatar
                IsBot = $user.bot
                JoinedAt = $member.joined_at
                Roles = $member.roles
                Nick = $member.nick
                GuildId = $GuildId
            }
        } else {
            $url = "https://discord.com/api/v10/users/$UserId"
            $user = Invoke-RestMethod -Uri $url -Headers $headers -ErrorAction Stop
            return [PSCustomObject]@{
                Id = $user.id
                Username = $user.username
                Discriminator = $user.discriminator
                GlobalName = $user.global_name
                Avatar = $user.avatar
                IsBot = $user.bot
                Flags = $user.public_flags
            }
        }
    } catch {
        Write-SysLog "Discord user info failed: $_" -Level 'ERROR'
        return $null
    }
}

function Manage-DiscordRoles {
    param([string]$BotToken, [string]$GuildId, [string]$UserId, [string]$RoleId, [ValidateSet('add','remove')][string]$Action = 'add')
    $headers = @{ Authorization = "Bot $BotToken" }
    $method = if ($Action -eq 'add') { 'PUT' } else { 'DELETE' }
    $url = "https://discord.com/api/v10/guilds/$GuildId/members/$UserId/roles/$RoleId"
    try {
        Invoke-RestMethod -Uri $url -Method $method -Headers $headers -ErrorAction Stop
        Write-SysLog "Discord role $Action on user $UserId in guild $GuildId" -Level 'INFO'
        return $true
    } catch {
        Write-SysLog "Discord role management failed: $_" -Level 'ERROR'
        return $false
    }
}

function Send-TelegramMessage {
    param([string]$BotToken, [string]$ChatId, [string]$Text, [string]$ParseMode = 'MarkdownV2', [switch]$DisableNotification, [switch]$DisableWebPreview, [int]$ReplyToMessageId = 0)
    $url = "https://api.telegram.org/bot$BotToken/sendMessage"
    $body = @{ chat_id = $ChatId; text = $Text; parse_mode = $ParseMode; disable_notification = $DisableNotification.IsPresent; disable_web_page_preview = $DisableWebPreview.IsPresent }
    if ($ReplyToMessageId -gt 0) { $body.reply_to_message_id = $ReplyToMessageId }
    try {
        $response = Invoke-RestMethod -Uri $url -Method Post -Body $body -ErrorAction Stop
        if ($response.ok) {
            Write-SysLog "Telegram message sent to $ChatId" -Level 'INFO'
            return [PSCustomObject]@{ Success=$true; MessageId=$response.result.message_id; Date=$response.result.date; Error=$null }
        }
        return [PSCustomObject]@{ Success=$false; MessageId=$null; Date=$null; Error=$response.description }
    } catch {
        Write-SysLog "Telegram send failed: $_" -Level 'ERROR'
        return [PSCustomObject]@{ Success=$false; MessageId=$null; Date=$null; Error=$_.Exception.Message }
    }
}

function Send-TelegramPhoto {
    param([string]$BotToken, [string]$ChatId, [string]$Photo, [string]$Caption = '')
    $url = "https://api.telegram.org/bot$BotToken/sendPhoto"
    $boundary = [System.Guid]::NewGuid().ToString()
    $multipart = "--$boundary`r\nContent-Disposition: form-data; name=`"chat_id`"`r`n`r`n$ChatId`r`n--$boundary`r\nContent-Disposition: form-data; name=`"caption`"`r`n`r`n$Caption`r`n--$boundary"
    if (Test-Path $Photo) {
        $multipart += "`r`nContent-Disposition: form-data; name=`"photo`"; filename=`"$(Split-Path $Photo -Leaf)`"`r`nContent-Type: image/jpeg`r`n`r`n"
        $fileBytes = [System.IO.File]::ReadAllBytes($Photo)
        $multipart += "$([System.Text.Encoding]::UTF8.GetString($fileBytes))`r`n--$boundary--`r`n"
    } else {
        $multipart += "`r`nContent-Disposition: form-data; name=`"photo`"`r`n`r`n$Photo`r`n--$boundary--`r`n"
    }
    $headers = @{ 'Content-Type' = "multipart/form-data; boundary=$boundary" }
    try {
        $response = Invoke-RestMethod -Uri $url -Method Post -Body $multipart -Headers $headers -ErrorAction Stop
        Write-SysLog "Telegram photo sent to $ChatId" -Level 'INFO'
        return $response.ok
    } catch {
        Write-SysLog "Telegram photo failed: $_" -Level 'ERROR'
        return $false
    }
}

function Get-TelegramUserInfo {
    param([string]$BotToken, [string]$ChatId)
    $url = "https://api.telegram.org/bot$BotToken/getChat"
    $body = @{ chat_id = $ChatId }
    try {
        $response = Invoke-RestMethod -Uri $url -Method Post -Body $body -ErrorAction Stop
        if ($response.ok) {
            $chat = $response.result
            return [PSCustomObject]@{
                Id = $chat.id
                Type = $chat.type
                Title = $chat.title
                FirstName = $chat.first_name
                LastName = $chat.last_name
                Username = $chat.username
                LanguageCode = $chat.language_code
                IsBot = $chat.is_bot
                CanJoinGroups = $chat.can_join_groups
                CanReadMessages = $chat.can_read_all_group_messages
            }
        }
        return $null
    } catch {
        Write-SysLog "Telegram user info failed: $_" -Level 'ERROR'
        return $null
    }
}

function Invoke-TelegramCommand {
    param([string]$BotToken, [string]$ChatId, [string]$Command)
    return Send-TelegramMessage -BotToken $BotToken -ChatId $ChatId -Text $Command
}

function Get-TelegramUpdates {
    param([string]$BotToken, [int]$Offset = 0, [int]$Timeout = 30)
    $url = "https://api.telegram.org/bot$BotToken/getUpdates"
    $body = @{ offset = $Offset; timeout = $Timeout }
    try {
        $response = Invoke-RestMethod -Uri $url -Method Post -Body $body -ErrorAction Stop
        if ($response.ok) { return $response.result }
        return @()
    } catch {
        Write-SysLog "Telegram updates failed: $_" -Level 'ERROR'
        return @()
    }
}

function Send-SlackMessage {
    param([string]$WebhookUrl = '', [string]$BotToken = '', [string]$Channel = '#general', [string]$Text, [string]$Username = 'CodeForge Bot', [string]$IconEmoji = ':robot_face:', [PSObject[]]$Blocks = @())
    if (-not $WebhookUrl -and -not $BotToken) { throw 'Either WebhookUrl or BotToken required' }
    $body = @{ text = $Text; username = $Username; icon_emoji = $IconEmoji }
    if ($WebhookUrl) { $body.channel = $Channel }
    if ($Blocks.Count) { $body.blocks = $Blocks }
    $json = $body | ConvertTo-Json -Depth 5
    try {
        if ($WebhookUrl) {
            Invoke-RestMethod -Uri $WebhookUrl -Method Post -Body $json -ContentType 'application/json' -ErrorAction Stop
        } else {
            $url = "https://slack.com/api/chat.postMessage"
            $headers = @{ Authorization = "Bearer $BotToken" }
            Invoke-RestMethod -Uri $url -Method Post -Body $json -Headers $headers -ContentType 'application/json' -ErrorAction Stop
        }
        Write-SysLog "Slack message sent to $Channel" -Level 'INFO'
        return $true
    } catch {
        Write-SysLog "Slack send failed: $_" -Level 'ERROR'
        return $false
    }
}

function Send-SlackFile {
    param([string]$BotToken, [string]$Channel, [string]$FilePath, [string]$InitialComment = '')
    if (-not (Test-Path $FilePath)) { throw "File not found: $FilePath" }
    $url = "https://slack.com/api/files.upload"
    $multipart = @{
        token = $BotToken
        channels = $Channel.Replace('#', '')
        file = Get-Item $FilePath
        initial_comment = $InitialComment
    }
    $response = Invoke-RestMethod -Uri $url -Method Post -Form $multipart -ErrorAction Stop
    if ($response.ok) {
        Write-SysLog "Slack file uploaded: $(Split-Path $FilePath -Leaf)" -Level 'INFO'
        return $true
    }
    Write-SysLog "Slack file upload failed: $($response.error)" -Level 'ERROR'
    return $false
}

function Get-SlackUserInfo {
    param([string]$BotToken, [string]$UserId, [switch]$IncludeProfile)
    $url = "https://slack.com/api/users.info"
    $headers = @{ Authorization = "Bearer $BotToken" }
    $body = @{ user = $UserId; include_locale = $true }
    try {
        $response = Invoke-RestMethod -Uri $url -Method Post -Body $body -Headers $headers -ErrorAction Stop
        if ($response.ok) {
            $user = $response.user
            $result = [PSCustomObject]@{
                Id = $user.id
                Name = $user.name
                RealName = $user.real_name
                Email = $user.profile.email
                IsAdmin = $user.is_admin
                IsOwner = $user.is_owner
                IsBot = $user.is_bot
                Timezone = $user.tz
                Updated = [datetime]::FromFileTimeUtc($user.updated * 10000000)
            }
            if ($IncludeProfile) { $result | Add-Member -NotePropertyName 'Profile' -NotePropertyValue $user.profile }
            return $result
        }
        return $null
    } catch {
        Write-SysLog "Slack user info failed: $_" -Level 'ERROR'
        return $null
    }
}

function Create-SlackChannel {
    param([string]$BotToken, [string]$Name, [switch]$IsPrivate, [string]$Topic = '')
    $url = "https://slack.com/api/conversations.create"
    $headers = @{ Authorization = "Bearer $BotToken" }
    $body = @{ name = $Name; is_private = $IsPrivate.IsPresent }
    try {
        $response = Invoke-RestMethod -Uri $url -Method Post -Body $body -Headers $headers -ErrorAction Stop
        if ($response.ok) {
            $channel = $response.channel
            if ($Topic) {
                $topicUrl = "https://slack.com/api/conversations.setTopic"
                $topicBody = @{ channel = $channel.id; topic = $Topic }
                Invoke-RestMethod -Uri $topicUrl -Method Post -Body $topicBody -Headers $headers -ErrorAction SilentlyContinue
            }
            Write-SysLog "Slack channel created: #$Name" -Level 'INFO'
            return [PSCustomObject]@{ Id = $channel.id; Name = $channel.name; Created = [datetime]::FromFileTimeUtc($channel.created * 10000000); IsPrivate = $IsPrivate.IsPresent; Success = $true }
        }
        return [PSCustomObject]@{ Success=$false; Error=$response.error }
    } catch {
        Write-SysLog "Slack channel creation failed: $_" -Level 'ERROR'
        return [PSCustomObject]@{ Success=$false; Error=$_.Exception.Message }
    }
}

function Send-TeamsMessage {
    param([string]$WebhookUrl, [string]$Title = 'Notification', [string]$Text, [string]$ThemeColor = '00FF00', [PSObject[]]$Sections = @(), [hashtable]$Facts = @{})
    $factList = @()
    foreach ($key in $Facts.Keys) { $factList += @{ name = $key; value = $Facts[$key] } }
    $body = @{
        title = $Title
        text = $Text
        themeColor = $ThemeColor
        sections = @()
    }
    if ($factList.Count) { $body.sections += @{ facts = $factList } }
    $body.sections += $Sections
    try {
        Invoke-RestMethod -Uri $WebhookUrl -Method Post -Body ($body | ConvertTo-Json -Depth 5) -ContentType 'application/json' -ErrorAction Stop
        Write-SysLog "Teams message sent: $Title" -Level 'INFO'
        return $true
    } catch {
        Write-SysLog "Teams send failed: $_" -Level 'ERROR'
        return $false
    }
}

function Send-TeamsAdaptiveCard {
    param([string]$WebhookUrl, [string]$CardJson)
    $body = @{ type = 'message'; attachments = @( @{ contentType = 'application/vnd.microsoft.card.adaptive'; contentUrl = $null; content = ($CardJson | ConvertFrom-Json) } ) }
    try {
        Invoke-RestMethod -Uri $WebhookUrl -Method Post -Body ($body | ConvertTo-Json -Depth 10) -ContentType 'application/json' -ErrorAction Stop
        Write-SysLog "Teams Adaptive Card sent" -Level 'INFO'
        return $true
    } catch {
        Write-SysLog "Teams Adaptive Card failed: $_" -Level 'ERROR'
        return $false
    }
}

function Get-TeamsUserViaGraph {
    param([string]$AccessToken, [string]$UserId = '', [string]$Filter = '')
    $headers = @{ Authorization = "Bearer $AccessToken" }
    $url = "https://graph.microsoft.com/v1.0/users"
    if ($UserId) { $url += "/$UserId" }
    if ($Filter) { $url += "?`$filter=$Filter" }
    try {
        $response = Invoke-RestMethod -Uri $url -Headers $headers -ErrorAction Stop
        $user = if ($UserId) { $response } else { $response.value[0] }
        return [PSCustomObject]@{
            Id = $user.id
            DisplayName = $user.displayName
            UserPrincipalName = $user.userPrincipalName
            Mail = $user.mail
            JobTitle = $user.jobTitle
            Department = $user.department
            MobilePhone = $user.mobilePhone
            BusinessPhones = $user.businessPhones
        }
    } catch {
        Write-SysLog "Teams Graph API failed: $_" -Level 'ERROR'
        return $null
    }
}

function Send-WhatsAppMessage {
    param([string]$PhoneNumberId, [string]$AccessToken, [string]$To, [string]$Text, [switch]$PreviewUrl)
    $url = "https://graph.facebook.com/v18.0/$PhoneNumberId/messages"
    $headers = @{ Authorization = "Bearer $AccessToken"; 'Content-Type' = 'application/json' }
    $body = @{
        messaging_product = 'whatsapp'
        recipient_type = 'individual'
        to = $To
        type = 'text'
        text = @{ body = $Text; preview_url = $PreviewUrl.IsPresent }
    }
    try {
        $response = Invoke-RestMethod -Uri $url -Method Post -Body ($body | ConvertTo-Json) -Headers $headers -ErrorAction Stop
        Write-SysLog "WhatsApp message sent to $To" -Level 'INFO'
        return [PSCustomObject]@{ Success=$true; MessageId=$response.messages[0].id; Error=$null }
    } catch {
        Write-SysLog "WhatsApp send failed: $_" -Level 'ERROR'
        return [PSCustomObject]@{ Success=$false; MessageId=$null; Error=$_.Exception.Message }
    }
}

function Send-WhatsAppTemplate {
    param([string]$PhoneNumberId, [string]$AccessToken, [string]$To, [string]$TemplateName, [string]$Language = 'fr', [PSObject[]]$Components = @())
    $url = "https://graph.facebook.com/v18.0/$PhoneNumberId/messages"
    $headers = @{ Authorization = "Bearer $AccessToken"; 'Content-Type' = 'application/json' }
    $body = @{
        messaging_product = 'whatsapp'
        to = $To
        type = 'template'
        template = @{ name = $TemplateName; language = @{ code = $Language } }
    }
    if ($Components.Count) { $body.template.components = $Components }
    $response = Invoke-RestMethod -Uri $url -Method Post -Body ($body | ConvertTo-Json -Depth 5) -Headers $headers -ErrorAction Stop
    Write-SysLog "WhatsApp template sent: $TemplateName" -Level 'INFO'
    return $response.ok
}

function Send-SignalMessage {
    param([string]$Account, [string]$Recipient, [string]$Message, [string]$Attachment = '')
    $cmd = "signal-cli -u $Account send -m `"$Message`" $Recipient"
    if ($Attachment -and (Test-Path $Attachment)) { $cmd = "signal-cli -u $Account send -a `"$Attachment`" -m `"$Message`" $Recipient" }
    try {
        $result = Invoke-Expression $cmd -ErrorAction Stop
        Write-SysLog "Signal message sent to $Recipient" -Level 'INFO'
        return $true
    } catch {
        Write-SysLog "Signal send failed: $_" -Level 'ERROR'
        return $false
    }
}

function Send-MattermostMessage {
    param([string]$ServerUrl, [string]$WebhookUrl = '', [string]$Token = '', [string]$ChannelId = '', [string]$Message, [string]$Username = 'CodeForge Bot', [string]$IconUrl = '')
    $url = if ($WebhookUrl) { $WebhookUrl } else { "$ServerUrl/api/v4/posts" }
    $headers = @{ 'Content-Type' = 'application/json' }
    if ($Token) { $headers.Authorization = "Bearer $Token" }
    $body = @{ message = $Message; username = $Username }
    if ($IconUrl) { $body.icon_url = $IconUrl }
    if ($ChannelId -and -not $WebhookUrl) { $body.channel_id = $ChannelId }
    try {
        Invoke-RestMethod -Uri $url -Method Post -Body ($body | ConvertTo-Json) -Headers $headers -ErrorAction Stop
        Write-SysLog "Mattermost message sent" -Level 'INFO'
        return $true
    } catch {
        Write-SysLog "Mattermost send failed: $_" -Level 'ERROR'
        return $false
    }
}

function Send-RocketChatMessage {
    param([string]$ServerUrl, [string]$WebhookToken = '', [string]$UserId = '', [string]$AuthToken = '', [string]$Channel, [string]$Message, [string]$Alias = 'CodeForge', [string]$Emoji = ':robot:')
    if ($WebhookToken) {
        $url = "$ServerUrl/hooks/$WebhookToken"
        $body = @{ text = $Message; channel = $Channel; alias = $Alias; emoji = $Emoji }
        Invoke-RestMethod -Uri $url -Method Post -Body ($body | ConvertTo-Json) -ContentType 'application/json' -ErrorAction Stop
    } else {
        $url = "$ServerUrl/api/v1/chat.postMessage"
        $headers = @{ 'X-Auth-Token' = $AuthToken; 'X-User-Id' = $UserId; 'Content-Type' = 'application/json' }
        $body = @{ channel = $Channel; text = $Message }
        Invoke-RestMethod -Uri $url -Method Post -Body ($body | ConvertTo-Json) -Headers $headers -ErrorAction Stop
    }
    Write-SysLog "Rocket.Chat message sent to $Channel" -Level 'INFO'
    return $true
}

function Send-MatrixMessage {
    param([string]$Homeserver, [string]$AccessToken, [string]$RoomId, [string]$Message, [string]$MessageType = 'm.text', [string]$Format = '', [string]$FormattedBody = '')
    $url = "$Homeserver/_matrix/client/v3/rooms/$RoomId/send/m.room.message"
    $headers = @{ Authorization = "Bearer $AccessToken"; 'Content-Type' = 'application/json' }
    $body = @{ msgtype = $MessageType; body = $Message }
    if ($Format -and $FormattedBody) { $body.format = $Format; $body.formatted_body = $FormattedBody }
    $txnId = [System.Guid]::NewGuid().ToString()
    $fullUrl = "$url/$txnId"
    try {
        $response = Invoke-RestMethod -Uri $fullUrl -Method Put -Body ($body | ConvertTo-Json) -Headers $headers -ErrorAction Stop
        Write-SysLog "Matrix message sent to room $RoomId" -Level 'INFO'
        return [PSCustomObject]@{ Success=$true; EventId=$response.event_id; Error=$null }
    } catch {
        Write-SysLog "Matrix send failed: $_" -Level 'ERROR'
        return [PSCustomObject]@{ Success=$false; EventId=$null; Error=$_.Exception.Message }
    }
}

function Get-MatrixUserInfo {
    param([string]$Homeserver, [string]$AccessToken, [string]$UserId)
    $url = "$Homeserver/_matrix/client/v3/profile/$UserId"
    $headers = @{ Authorization = "Bearer $AccessToken" }
    try {
        $profile = Invoke-RestMethod -Uri $url -Headers $headers -ErrorAction Stop
        $presUrl = "$Homeserver/_matrix/client/v3/presence/$UserId/status"
        $presence = Invoke-RestMethod -Uri $presUrl -Headers $headers -ErrorAction SilentlyContinue
        return [PSCustomObject]@{
            UserId = $UserId
            DisplayName = $profile.displayname
            AvatarUrl = $profile.avatar_url
            Presence = if ($presence) { $presence.presence } else { 'unknown' }
            StatusMsg = if ($presence) { $presence.status_msg } else { $null }
        }
    } catch {
        Write-SysLog "Matrix user info failed: $_" -Level 'ERROR'
        return $null
    }
}

function Broadcast-MultiPlatform {
    param([string]$Message, [hashtable]$Platforms, [switch]$Parallel)
    $results = @{}
    $successCount = 0
    $failCount = 0
    foreach ($platform in $Platforms.Keys) {
        $config = $Platforms[$platform]
        try {
            switch ($platform.ToLower()) {
                'discord' { Send-DiscordMessage -WebhookUrl $config.webhook -Content $Message -ErrorAction Stop }
                'slack'   { Send-SlackMessage -WebhookUrl $config.webhook -Text $Message -ErrorAction Stop }
                'teams'   { Send-TeamsMessage -WebhookUrl $config.webhook -Title 'Broadcast' -Text $Message -ErrorAction Stop }
                'telegram'{ Send-TelegramMessage -BotToken $config.token -ChatId $config.chat -Text $Message -ErrorAction Stop }
                'whatsapp'{ Send-WhatsAppMessage -PhoneNumberId $config.phoneId -AccessToken $config.token -To $config.to -Text $Message -ErrorAction Stop }
                default   { Write-SysLog "Unknown platform: $platform" -Level 'WARN' }
            }
            $results[$platform] = 'Success'
            $successCount++
        } catch {
            $results[$platform] = "Error: $_"
            $failCount++
            Write-SysLog "Broadcast to $platform failed: $_" -Level 'ERROR'
        }
    }
    Write-SysLog "Broadcast completed: $successCount success, $failCount failures" -Level 'INFO'
    return [PSCustomObject]@{ SuccessCount=$successCount; FailCount=$failCount; Results=$results }
}

async function getIMPlatformStatus(platforms = ['discord','telegram','slack']) {
    const checks = {
        discord: async () => { const r = await fetch('https://discord.com/api/v10/gateway'); return r.ok },
        telegram: async () => { const r = await fetch('https://api.telegram.org/bot/getMe'); return r.ok },
        slack: async () => { const r = await fetch('https://slack.com/api/api.test'); return r.ok },
        teams: async () => { const r = await fetch('https://graph.microsoft.com/v1.0'); return r.status === 401 },
        whatsapp: async () => { const r = await fetch('https://graph.facebook.com/v18.0'); return r.status === 400 }
    };
    const results = {};
    for (const p of platforms) {
        if (checks[p]) results[p] = await checks[p]();
        else results[p] = false;
    }
    return results;
}
